window.refreshHomeLeads=function(){
  var slot=document.getElementById('home-lead-tasks-slot');
  var empty=document.getElementById('home-tasks-empty');
  var countEl=document.getElementById('home-lead-count');
  var NEXT={new:'Send the welcome email',to_contact:'Send the welcome email',contacted:'Qualify the property',qualified:'Book a viewing',viewing:'Send a proposal',proposal:'Send the contract',contract_sent:'Chase the signature',signed:'Start onboarding',onboarding:'Go live'};
  var LABEL={new:'New',to_contact:'To contact',contacted:'Contacted',qualified:'Qualified',viewing:'Viewing',proposal:'Proposal',contract_sent:'Contract sent',signed:'Signed',onboarding:'Onboarding'};
  var STEPS=['new','to_contact','contacted','qualified','viewing','proposal','contract_sent','signed','onboarding','live'];
  function homeLeadsExpanded(){
    try{
      var v=localStorage.getItem('home_leads_expanded');
      // Default: extended (open). Only collapse when the user explicitly minimises.
      if(v===null||v===undefined||v==='') return true;
      return v!=='0' && v!=='false';
    }catch(e){ return true; }
  }
  window.toggleHomeLeads=function(ev){
    if(ev){ ev.preventDefault(); ev.stopPropagation(); }
    var open=!homeLeadsExpanded();
    try{ localStorage.setItem('home_leads_expanded', open?'1':'0'); }catch(e){}
    if(typeof window.refreshHomeLeads==='function') window.refreshHomeLeads();
  };
  function paint(pack){
    var mine=pack.mine||[];
    if(countEl) countEl.textContent=String(mine.length);
    if(!slot) return;
    if(!pack.me || !mine.length){ slot.style.display='none'; return; }
    if(empty && empty.parentNode) empty.parentNode.removeChild(empty);
    slot.style.display='';
    var open=homeLeadsExpanded();
    var arrow=open?'▾':'▸';
    var head='<h3 class="home-leads-h" style="cursor:pointer;user-select:none" onclick="toggleHomeLeads(event)" title="'+(open?'Minimise open leads':'Show open leads')+'">' +
      '<span class="dot" style="background:var(--gold)"></span>Open leads <span class="cnt">'+mine.length+'</span>' +
      '<span class="home-leads-arrow" style="margin-left:auto;color:var(--tx3);font-size:12px;line-height:1">'+arrow+'</span></h3>';
    var body='';
    if(open){
      // Extended view: full assigned open-lead list (not a truncated preview).
      body=mine.map(function(l){
        var act=NEXT[l.stage]||'Open the ticket';
        var si=STEPS.indexOf(l.stage);
        var pipe=si>=0?('Step '+(si+1)+' of 10 · '+(LABEL[l.stage]||l.stage)):(LABEL[l.stage]||l.stage);
        var raw=String(l.full_name||'').trim().replace(/\s+/g,' ');
        var name=!raw?'(no name)':(raw===raw.toUpperCase()||raw===raw.toLowerCase())?raw.toLowerCase().replace(/(^|[\s'\-])(\S)/g,function(_,a,b){return a+b.toUpperCase();}):raw;
        var sub=pipe+(l.property_address?(' · '+l.property_address):'');
        return '<div class="home-row" style="cursor:pointer" onclick="ldGoTask('+l.id+')"><span class="dot" style="background:var(--gold)"></span><div class="rl"><b>'+esc(name)+'</b><div class="meta">Lead · '+esc(sub)+'</div></div><span class="lnk">'+esc(act)+' →</span></div>';
      }).join('');
    }
    slot.innerHTML=head+body;
  }
  if(typeof window.ldFetchMyTasks==='function'){
    window.ldFetchMyTasks().then(paint).catch(function(){ if(countEl) countEl.textContent='—'; });
  } else if(countEl){ countEl.textContent='—'; }
};

