function homeIsOpenLead(l){
  return !!(l && l.owner && !l.archived_at && l.status === 'open' && l.stage !== 'on_hold');
}
function homeInspectWhen(l){ return l && (l.inspection_at || l.inspectionAt); }
function homeWhoLabel(key, cfg){
  if (key === 'giannis' || key === 'john') return 'John';
  if (key === 'kostas') return 'Kostas';
  if (key === 'michalis') return 'Michalis';
  var m = ((cfg && cfg.team) || []).filter(function (t) { return t.key === key; })[0];
  if (m && m.name) return m.name;
  if (!key) return '';
  return String(key).charAt(0).toUpperCase() + String(key).slice(1);
}
function homeInspectionTitle(l, cfg){
  var iso = homeInspectWhen(l);
  var d = iso ? new Date(iso) : null;
  var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var day = (d && !isNaN(d.getTime())) ? (d.getDate() + ' ' + months[d.getMonth()]) : '';
  var who = homeWhoLabel((l && (l.inspection_by || l.inspectionBy || l.owner)) || '', cfg);
  return 'Property Inspection · ' + who + ' · ' + day;
}
window.refreshHomeLeads=function(){
  var slot=document.getElementById('home-lead-tasks-slot');
  var empty=document.getElementById('home-tasks-empty');
  var countEl=document.getElementById('home-lead-count');
  var weekEl=document.getElementById('home-week-cal');
  function fmtTime(d){
    var h=d.getHours(), mi=d.getMinutes();
    return (h<10?'0':'')+h+':'+(mi<10?'0':'')+mi;
  }
  function paint(pack){
    var cfg=pack.cfg||{};
    var leads=pack.leads||[];
    var open=leads.filter(homeIsOpenLead);
    if(countEl) countEl.textContent=String(open.length);
    var appts=open.filter(function(l){ return !!homeInspectWhen(l); }).sort(function(a,b){
      return new Date(homeInspectWhen(a)) - new Date(homeInspectWhen(b));
    });
    if(slot){
      if(empty && empty.parentNode && appts.length) empty.parentNode.removeChild(empty);
      slot.style.display='';
      var body;
      if(!appts.length){
        body='<div class="home-empty">No viewings booked yet. On a qualified lead, use Book a viewing.</div>';
      } else {
        body=appts.map(function(l){
          var when=new Date(homeInspectWhen(l));
          var title=homeInspectionTitle(l, cfg);
          var raw=String(l.full_name||'').trim().replace(/\s+/g,' ');
          var name=!raw?'(no name)':(raw===raw.toUpperCase()||raw===raw.toLowerCase())?raw.toLowerCase().replace(/(^|[\s'\-])(\S)/g,function(_,a,b){return a+b.toUpperCase();}):raw;
          var sub=name+(l.property_address?(' · '+l.property_address):'')+(isNaN(when.getTime())?'':' · '+fmtTime(when));
          return '<div class="home-row" style="cursor:pointer" onclick="ldGoTask('+l.id+')"><span class="dot" style="background:var(--gold)"></span><div class="rl"><b>'+esc(title)+'</b><div class="meta">'+esc(sub)+'</div></div><span class="lnk">Open →</span></div>';
        }).join('');
      }
      slot.innerHTML='<h3><span class="dot" style="background:var(--gold)"></span>Appointments <span class="cnt">'+appts.length+'</span></h3>'+body;
    }
    if(weekEl){
      var today=new Date(); today=new Date(today.getFullYear(),today.getMonth(),today.getDate());
      var days=[];
      for(var i=0;i<7;i++) days.push(new Date(today.getFullYear(),today.getMonth(),today.getDate()+i));
      var wd=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
      weekEl.style.display='';
      weekEl.innerHTML='<h3><i class="ti ti-calendar-event"></i> Viewings this week</h3><div class="home-week">'+days.map(function(d){
        var items=appts.filter(function(l){
          var w=new Date(homeInspectWhen(l));
          return w.getFullYear()===d.getFullYear() && w.getMonth()===d.getMonth() && w.getDate()===d.getDate();
        });
        var cells=items.map(function(l){
          var w=new Date(homeInspectWhen(l));
          var who=homeWhoLabel(l.inspection_by||l.inspectionBy||l.owner, cfg);
          return '<div class="home-week-item" onclick="ldGoTask('+l.id+')">'+esc(fmtTime(w)+' · '+who)+'</div>';
        }).join('') || '<div class="home-week-empty">—</div>';
        var isToday=d.getTime()===today.getTime();
        return '<div class="home-week-day'+(isToday?' today':'')+'"><div class="home-week-d">'+wd[d.getDay()]+' '+d.getDate()+'</div>'+cells+'</div>';
      }).join('')+'</div>';
    }
  }
  if(typeof window.ldFetchMyTasks==='function'){
    window.ldFetchMyTasks().then(paint).catch(function(){ if(countEl) countEl.textContent='—'; });
  } else if(countEl){ countEl.textContent='—'; }
};

