window.ldStage = function (id, stage) {
  var l = lead(id); if (!l || l.stage === stage) return;
  var body = { stage: stage, by: who() };
  if (stage === 'lost') {
    var why = prompt('Why was this lead lost?');
    if (why === null) return;
    if (!String(why).trim()) { toast('A lost lead needs a reason.', 'err'); return; }
    body.lostReason = String(why).trim();
  }
  jsend('/api/leads/' + id, 'PATCH', body).then(function (r) { after(r, 'Moved to ' + (LABEL[stage] || stage) + '.'); });
};

