window.ldBookViewingClose = function () {
  var ov = document.getElementById('ld-view-ov');
  if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
};
function viewingTeam() {
  var list = (cfg.team || []).slice();
  var have = {};
  list.forEach(function (t) { if (t && t.key) have[t.key] = 1; });
  [{ key: 'kostas', name: 'Kostas' }, { key: 'michalis', name: 'Michalis' }].forEach(function (t) {
    if (!have[t.key]) list.push(t);
  });
  return list;
}
function viewingLocalParts(iso) {
  var pad = function (n) { return (n < 10 ? '0' : '') + n; };
  var d = iso ? new Date(iso) : new Date();
  if (isNaN(d.getTime())) d = new Date();
  if (!iso) d.setHours(10, 0, 0, 0);
  return {
    date: d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()),
    time: pad(d.getHours()) + ':' + pad(d.getMinutes())
  };
}
window.ldBookViewing = function (id) {
  var l = lead(id); if (!l) return;
  window.ldBookViewingClose();
  var parts = viewingLocalParts(l.inspection_at || l.inspectionAt);
  var whoKey = l.inspection_by || l.inspectionBy || l.owner || meKey() || '';
  var opts = viewingTeam().map(function (t) {
    return '<option value="' + esc(t.key) + '"' + (t.key === whoKey ? ' selected' : '') + '>' + esc(displayName(t.key) || t.name) + '</option>';
  }).join('');
  var ov = document.createElement('div');
  ov.id = 'ld-view-ov';
  ov.innerHTML = ''
    + '<div class="ld-wel" role="dialog" aria-label="Book a viewing">'
    + '<div class="ld-wel-h"><div><h3>Book a viewing</h3>'
    + '<div style="font-size:12px;color:var(--tx3);margin-top:2px">' + esc(prettyPerson(l.full_name) || '(no name)') + (l.property_address ? (' · ' + esc(l.property_address)) : '') + '</div>'
    + '</div><button type="button" class="btn sm" onclick="ldBookViewingClose()">✕</button></div>'
    + '<div class="ld-wel-b">'
    + '<div class="ld-wel-row">'
    + '<div style="flex:1;min-width:140px"><label>Date</label><input id="ld-view-date" type="date" value="' + esc(parts.date) + '"/></div>'
    + '<div style="width:120px"><label>Time</label><input id="ld-view-time" type="time" value="' + esc(parts.time) + '"/></div>'
    + '</div>'
    + '<div><label>Who goes</label><select id="ld-view-who">' + opts + '</select></div>'
    + '<div style="font-size:12px;color:var(--tx3)">This books a Property Inspection on Home. Completing the visit does not close the lead — proposal is the next step.</div>'
    + '</div>'
    + '<div class="ld-wel-f">'
    + '<button type="button" class="btn sm" onclick="ldBookViewingClose()">Cancel</button>'
    + '<button type="button" class="btn sm primary" id="ld-view-save" onclick="ldBookViewingSave(' + id + ')">Save viewing</button>'
    + '</div></div>';
  ov.addEventListener('click', function (ev) { if (ev.target === ov) ldBookViewingClose(); });
  document.body.appendChild(ov);
};
window.ldBookViewingSave = function (id) {
  var dateEl = document.getElementById('ld-view-date');
  var timeEl = document.getElementById('ld-view-time');
  var whoEl = document.getElementById('ld-view-who');
  var date = dateEl ? String(dateEl.value || '').trim() : '';
  var time = timeEl ? String(timeEl.value || '').trim() : '10:00';
  var whoBy = whoEl ? String(whoEl.value || '').trim() : '';
  if (!date) { toast('Pick a viewing date.', 'err'); return; }
  if (!time) time = '10:00';
  var when = new Date(date + 'T' + time + ':00');
  if (isNaN(when.getTime())) { toast('That date and time is not valid.', 'err'); return; }
  var l = lead(id);
  var body = {
    stage: 'viewing',
    inspectionAt: when.toISOString(),
    inspectionBy: whoBy || (l && l.owner) || '',
    by: who()
  };
  var btn = document.getElementById('ld-view-save');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  jsend('/api/leads/' + id, 'PATCH', body).then(function (r) {
    window.ldBookViewingClose();
    after(r, 'Viewing booked for ' + date + ' at ' + time + '.');
    try { if (typeof window.refreshHomeLeads === 'function') window.refreshHomeLeads(); } catch (e) {}
  });
};

